<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kanban Board</title>
  <style>
    * {
      box-sizing: border-box;
    }

    :root {
      color-scheme: light;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background: #f3f5f9;
      color: #172033;
    }

    body {
      min-height: 100vh;
      margin: 0;
      padding: 40px 20px;
      background:
        radial-gradient(circle at top left, rgba(99, 102, 241, 0.12), transparent 28rem),
        #f3f5f9;
    }

    .app {
      width: min(1180px, 100%);
      margin: 0 auto;
    }

    .topbar {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 28px;
    }

    .title-group h1 {
      margin: 0;
      font-size: clamp(1.8rem, 4vw, 2.6rem);
      letter-spacing: -0.04em;
    }

    .title-group p {
      margin: 7px 0 0;
      color: #697386;
    }

    .add-form {
      display: flex;
      gap: 10px;
      width: min(470px, 100%);
    }

    #new-card {
      min-width: 0;
      flex: 1;
      height: 44px;
      padding: 0 14px;
      border: 1px solid #d9deea;
      border-radius: 10px;
      outline: none;
      background: #fff;
      color: #172033;
      font: inherit;
      box-shadow: 0 3px 12px rgba(28, 39, 62, 0.05);
      transition: border-color 0.2s, box-shadow 0.2s;
    }

    #new-card:focus {
      border-color: #6366f1;
      box-shadow: 0 0 0 4px rgba(99, 102, 241, 0.13);
    }

    #add-card {
      height: 44px;
      padding: 0 18px;
      border: 0;
      border-radius: 10px;
      background: #4f46e5;
      color: #fff;
      font: 700 0.92rem inherit;
      cursor: pointer;
      box-shadow: 0 5px 14px rgba(79, 70, 229, 0.25);
      transition: transform 0.15s, background 0.15s;
    }

    #add-card:hover {
      background: #4338ca;
      transform: translateY(-1px);
    }

    #add-card:active {
      transform: translateY(0);
    }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
      align-items: start;
    }

    .column {
      min-height: 420px;
      padding: 16px;
      border: 1px solid #e1e5ee;
      border-radius: 16px;
      background: rgba(248, 249, 252, 0.88);
      box-shadow: 0 12px 28px rgba(29, 38, 58, 0.07);
      transition: border-color 0.2s, background 0.2s, transform 0.2s;
    }

    .column.drag-over {
      border-color: #6366f1;
      background: #eef0ff;
      transform: translateY(-2px);
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 15px;
      padding: 2px 3px;
    }

    .column-title {
      display: flex;
      align-items: center;
      gap: 9px;
      margin: 0;
      font-size: 1rem;
    }

    .column-title::before {
      width: 9px;
      height: 9px;
      border-radius: 50%;
      background: #94a3b8;
      content: "";
    }

    #col-todo .column-title::before {
      background: #f59e0b;
    }

    #col-doing .column-title::before {
      background: #3b82f6;
    }

    #col-done .column-title::before {
      background: #10b981;
    }

    .count {
      display: inline-grid;
      min-width: 27px;
      height: 27px;
      place-items: center;
      padding: 0 8px;
      border-radius: 999px;
      background: #e8ebf2;
      color: #596275;
      font-size: 0.78rem;
      font-weight: 800;
    }

    .cards {
      min-height: 340px;
      display: flex;
      flex-direction: column;
      gap: 11px;
    }

    .card {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      padding: 15px;
      border: 1px solid #e2e6ef;
      border-radius: 12px;
      background: #fff;
      box-shadow: 0 5px 14px rgba(30, 41, 59, 0.07);
      cursor: grab;
      transition: transform 0.15s, box-shadow 0.15s, opacity 0.15s;
    }

    .card:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 20px rgba(30, 41, 59, 0.1);
    }

    .card.dragging {
      opacity: 0.45;
      cursor: grabbing;
    }

    .card-title {
      min-width: 0;
      overflow-wrap: anywhere;
      line-height: 1.45;
    }

    .card-del {
      flex: 0 0 auto;
      display: grid;
      width: 27px;
      height: 27px;
      place-items: center;
      padding: 0;
      border: 0;
      border-radius: 7px;
      background: #f3f4f6;
      color: #70798a;
      font: 700 1rem/1 inherit;
      cursor: pointer;
      transition: background 0.15s, color 0.15s;
    }

    .card-del:hover {
      background: #fee2e2;
      color: #dc2626;
    }

    @media (max-width: 760px) {
      body {
        padding: 24px 14px;
      }

      .topbar {
        align-items: stretch;
        flex-direction: column;
      }

      .add-form {
        width: 100%;
      }

      .board {
        grid-template-columns: 1fr;
      }

      .column {
        min-height: 260px;
      }

      .cards {
        min-height: 180px;
      }
    }
  </style>
</head>
<body>
  <main class="app">
    <div class="topbar">
      <div class="title-group">
        <h1>Kanban Board</h1>
        <p>Organize tasks and keep work moving.</p>
      </div>

      <div class="add-form">
        <input id="new-card" type="text" placeholder="Add a new task…" aria-label="New card title">
        <button id="add-card" type="button">Add task</button>
      </div>
    </div>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo">
        <header class="column-header">
          <h2 class="column-title">To Do</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="cards"></div>
      </section>

      <section class="column" id="col-doing">
        <header class="column-header">
          <h2 class="column-title">Doing</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="cards"></div>
      </section>

      <section class="column" id="col-done">
        <header class="column-header">
          <h2 class="column-title">Done</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="cards"></div>
      </section>
    </section>
  </main>

  <script>
    (() => {
      const STORAGE_KEY = "kanban-board-state";
      const columnIds = ["col-todo", "col-doing", "col-done"];
      const input = document.getElementById("new-card");
      const addButton = document.getElementById("add-card");
      let draggedCard = null;

      function createCard(title, id = crypto.randomUUID()) {
        const card = document.createElement("article");
        card.className = "card";
        card.draggable = true;
        card.dataset.id = id;

        const titleElement = document.createElement("span");
        titleElement.className = "card-title";
        titleElement.textContent = title;

        const deleteButton = document.createElement("button");
        deleteButton.className = "card-del";
        deleteButton.type = "button";
        deleteButton.textContent = "×";
        deleteButton.setAttribute("aria-label", `Delete ${title}`);

        deleteButton.addEventListener("click", () => {
          card.remove();
          updateCounts();
          saveBoard();
        });

        card.addEventListener("dragstart", event => {
          draggedCard = card;
          card.classList.add("dragging");
          event.dataTransfer.effectAllowed = "move";
          event.dataTransfer.setData("text/plain", card.dataset.id);
        });

        card.addEventListener("dragend", () => {
          draggedCard = null;
          card.classList.remove("dragging");
          document.querySelectorAll(".column").forEach(column => {
            column.classList.remove("drag-over");
          });
        });

        card.append(titleElement, deleteButton);
        return card;
      }

      function updateCounts() {
        columnIds.forEach(columnId => {
          const column = document.getElementById(columnId);
          const count = column.querySelectorAll(".card").length;
          const countElement = column.querySelector(".count");
          countElement.textContent = count;
          countElement.setAttribute("aria-label", `${count} card${count === 1 ? "" : "s"}`);
        });
      }

      function saveBoard() {
        const state = {};

        columnIds.forEach(columnId => {
          state[columnId] = Array.from(
            document.querySelectorAll(`#${columnId} .card`)
          ).map(card => ({
            id: card.dataset.id,
            title: card.querySelector(".card-title").textContent
          }));
        });

        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      }

      function loadBoard() {
        let state;

        try {
          state = JSON.parse(localStorage.getItem(STORAGE_KEY));
        } catch {
          state = null;
        }

        if (state && typeof state === "object") {
          columnIds.forEach(columnId => {
            const container = document.querySelector(`#${columnId} .cards`);
            const cards = Array.isArray(state[columnId]) ? state[columnId] : [];

            cards.forEach(cardData => {
              if (cardData && typeof cardData.title === "string") {
                container.appendChild(createCard(cardData.title, cardData.id));
              }
            });
          });
        }

        updateCounts();
      }

      function addCard() {
        const title = input.value.trim();
        if (!title) return;

        document.querySelector("#col-todo .cards").appendChild(createCard(title));
        input.value = "";
        input.focus();
        updateCounts();
        saveBoard();
      }

      addButton.addEventListener("click", addCard);

      input.addEventListener("keydown", event => {
        if (event.key === "Enter") addCard();
      });

      columnIds.forEach(columnId => {
        const column = document.getElementById(columnId);

        column.addEventListener("dragover", event => {
          event.preventDefault();
          event.dataTransfer.dropEffect = "move";
          column.classList.add("drag-over");
        });

        column.addEventListener("dragleave", event => {
          if (!column.contains(event.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });

        column.addEventListener("drop", event => {
          event.preventDefault();
          column.classList.remove("drag-over");

          const id = event.dataTransfer.getData("text/plain");
          const card = draggedCard || document.querySelector(`.card[data-id="${CSS.escape(id)}"]`);

          if (card) {
            column.querySelector(".cards").appendChild(card);
            updateCounts();
            saveBoard();
          }
        });
      });

      loadBoard();
    })();
  </script>
</body>
</html>
